package com.trampolim.api.hub;
import jakarta.servlet.*;import jakarta.servlet.http.*;import java.io.*;import java.util.concurrent.Semaphore;
import org.springframework.beans.factory.ObjectProvider;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.web.filter.OncePerRequestFilter;import org.springframework.web.server.ResponseStatusException;
public class HubLogoUploadFilter extends OncePerRequestFilter {
 private final ObjectProvider<HubAccess> access;private final Semaphore slots=new Semaphore(2);
 public HubLogoUploadFilter(ObjectProvider<HubAccess> access){this.access=access;}
 @Override protected boolean shouldNotFilter(HttpServletRequest request){return !request.getMethod().equals("POST")||!request.getRequestURI().matches("/api/empresas/hub/organizations/[0-9]+/logo");}
 @Override protected void doFilterInternal(HttpServletRequest request,HttpServletResponse response,FilterChain chain)throws ServletException,IOException{int error=0;boolean acquired=false;try{var auth=SecurityContextHolder.getContext().getAuthentication();if(auth==null||!auth.isAuthenticated())error=401;else{var service=access.getIfAvailable();if(service==null)error=503;else{long id=Long.parseLong(request.getRequestURI().split("/")[5]);service.require(auth.getName(),id,true);service.additionalWrite(id);long length=request.getContentLengthLong();if(length<0)error=411;else if(length>1114112)error=413;else if(!(acquired=slots.tryAcquire()))error=429;}}}catch(ResponseStatusException denied){error=denied.getStatusCode().value();}catch(org.springframework.dao.DataAccessException unavailable){error=503;}catch(NumberFormatException invalid){error=400;}try{if(error!=0){response.setStatus(error);response.setContentType("application/json;charset=UTF-8");response.getWriter().write(new com.fasterxml.jackson.databind.ObjectMapper().writeValueAsString(java.util.Map.of("detail","Envio de logotipo indisponível. Verifique permissão e limite de 1 MB.")));return;}chain.doFilter(request,response);}finally{if(acquired)slots.release();}}
}
